type Schema = Record<string, unknown>
const ref = (name: string): Schema => ({ $ref: `#/components/schemas/${name}` })
const str = (extra: Schema = {}): Schema => ({ type: 'string', ...extra })
const uuid = (): Schema => str({ format: 'uuid' })
const timestamp = (): Schema => str({ format: 'date-time' })
const nullable = (schema: Schema): Schema => ({ anyOf: [schema, { type: 'null' }] })
const array = (items: Schema, extra: Schema = {}): Schema => ({ type: 'array', items, ...extra })
const object = (properties: Record<string, Schema> = {}, required: string[] = [], extra: Schema = {}): Schema => ({
  type: 'object', properties, ...(required.length ? { required } : {}), ...extra,
})
const body = (schema: Schema, example?: unknown) => ({
  required: true,
  content: { 'application/json': { schema, ...(example === undefined ? {} : { example }) } },
})
const response = (description: string, schema?: Schema, example?: unknown) => ({
  description,
  ...(schema ? { content: { 'application/json': { schema, ...(example === undefined ? {} : { example }) } } } : {}),
})
const ok = (schema: Schema, example?: unknown) => response('Success', schema, example)
const error = (description = 'Request rejected') => response(description, ref('Error'), { error: description })
const success = ref('Success')
const pathId = (name: string, description?: string) => ({ name, in: 'path', required: true, ...(description ? { description } : {}), schema: uuid() })
const query = (name: string, schema: Schema, description?: string) => ({ name, in: 'query', required: false, ...(description ? { description } : {}), schema })
const auth = [{ bearer: [] }, { session: [] }]
const secured = (permission?: string) => permission
  ? `Requires ${permission === 'automations:manage' ? 'both workspace `automations:manage` and `items:read` permissions' : `the workspace \`${permission}\` permission`}. Workspace and resource identifiers are revalidated against the authenticated user.`
  : 'Requires an authenticated account.'

const event = str({ enum: [...events] })
const priority = str({ enum: ['none', 'low', 'medium', 'high', 'urgent'] })
const nodeIcon = nullable(str({ enum: ['diamond', 'briefcase', 'target', 'folder', 'archive', 'bookmark', 'list', 'checklist', 'calendar', 'flag'] }))
const nodeColor = nullable(str({ enum: ['slate', 'orange', 'amber', 'green', 'teal', 'blue', 'violet', 'rose'] }))
const date = nullable(str({ format: 'date', pattern: '^\\d{4}-\\d{2}-\\d{2}$' }))
const hexColor = str({ pattern: '^#[0-9a-fA-F]{6}$', example: '#2f7d32' })
