  components: {
    securitySchemes: {
      bearer: { type: 'http', scheme: 'bearer', description: 'Raw API token returned once by POST /auth/tokens.' },
      session: { type: 'apiKey', in: 'cookie', name: 'hopya_session', description: 'HttpOnly browser session; unsafe requests also require a matching Origin.' },
    },
    schemas,
  },
